from pathlib import Path
import re

path=Path('vision-sync.js')
text=path.read_text('utf-8')
text=text.replace("const CONTRACT='ANCHOR_FREE_STRUCTURAL_V4';","const CONTRACT='ANCHOR_FREE_STRUCTURAL_V5';")
text=text.replace('COARSE_BEAM=18','COARSE_BEAM=8')

fast=r'''function structuralPhaseScoreFast(source,field,cx,cy,radius,angle){if(!source?.high||!field?.high||radius<=0)return{score:-1,ncc:-1,count:0};const mx=(source.w-1)/2,my=(source.h-1)/2,a=rad(angle),c=Math.cos(a),s=Math.sin(a);let sumS=0,sumT=0,sumSS=0,sumTT=0,sumST=0,count=0;for(let sy=6;sy<source.h-6;sy+=4)for(let sx=6;sx<source.w-6;sx+=4){const nx=(sx-mx)/(source.w/2),ny=(sy-my)/(source.h/2),ring=Math.hypot(nx,ny);if(ring<.18||ring>.80)continue;const tx=Math.round(cx+(nx*c-ny*s)*radius),ty=Math.round(cy+(nx*s+ny*c)*radius);if(tx<2||ty<2||tx>=field.w-2||ty>=field.h-2)continue;const sv=source.high[sy*source.w+sx],tv=field.high[ty*field.w+tx];sumS+=sv;sumT+=tv;sumSS+=sv*sv;sumTT+=tv*tv;sumST+=sv*tv;count++}if(count<48)return{score:-1,ncc:-1,count};const cov=sumST-sumS*sumT/count,va=sumSS-sumS*sumS/count,vb=sumTT-sumT*sumT/count,ncc=va>1e-7&&vb>1e-7?cov/Math.sqrt(va*vb):-1;return{score:clamp((ncc+.12)/1.12,0,1),ncc,count}}
'''
if 'function structuralPhaseScoreFast(' not in text:
    text=text.replace('function structuralPhaseScore(',fast+'function structuralPhaseScore(',1)

coarse=r'''async function coarseMatch(info,cfg){const atlas=await coarseAtlas(cfg),field=atlas.field,samples=info.samples,stride=cfg.width===32768?7:4,radii=cfg.width===32768?[6,9,13,18,25,34]:[5,8,12,17,24],angles=[0,45,90,135,180,225,270,315],topByRadius=new Map(radii.map(r=>[r,[]]));let bestSeen=0,rows=0;for(let y=stride;y<field.h-stride;y+=stride){for(let x=stride;x<field.w-stride;x+=stride){const target=pixelToGlobal(x*atlas.factor,y*atlas.factor,COARSE_Z,cfg);if(!inGlobalBounds(target))continue;for(const radius of radii)for(const angle of angles){const phase=structuralPhaseScoreFast(info.field,field,x,y,radius,angle);if(phase.score<0)continue;pushTop(topByRadius.get(radius),{x,y,radius,angle,score:phase.score,phaseFast:phase.score},110);bestSeen=Math.max(bestSeen,phase.score)}}rows++;if(rows%5===0){state.coarseScore=bestSeen;setDiag('SEARCH',`global structural phase ${Math.round(y/field.h*100)}%`,'coarse-global');await sleep(0)}}const seeds=[];for(const radius of radii){const pool=topByRadius.get(radius)||[];for(const item of pool.slice(0,90)){const sparse=scoreAt(field,item.x,item.y,template(samples,item.radius,item.angle)),dense=denseStructuralScore(info.field,field,item.x,item.y,item.radius,item.angle),contour=bidirectionalContourScore(info.field,field,item.x,item.y,item.radius,item.angle),phase=structuralPhaseScore(info.field,field,item.x,item.y,item.radius,item.angle);item.sparseScore=sparse.score;item.structureScore=sparse.score;item.denseScore=dense.score;item.contourScore=contour.score;item.phaseScore=phase.score;item.rankScore=.06*Math.max(0,sparse.score)+.08*Math.max(0,dense.score)+.20*Math.max(0,contour.score)+.66*Math.max(0,phase.score)}pool.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));const chosen=[];for(const item of pool){if(chosen.every(seed=>Math.hypot(item.x-seed.x,item.y-seed.y)>=Math.max(11,radius*.50))){chosen.push(item);seeds.push(item);if(chosen.length>=7)break}}}seeds.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));if(!seeds.length)return null;const hypotheses=[];for(const seed of seeds.slice(0,30)){const phaseTop=[];for(let y=seed.y-stride*1.5;y<=seed.y+stride*1.5;y+=2)for(let x=seed.x-stride*1.5;x<=seed.x+stride*1.5;x+=2){const target=pixelToGlobal(x*atlas.factor,y*atlas.factor,COARSE_Z,cfg);if(!inGlobalBounds(target))continue;for(const rf of [.86,.92,.97,1,1.03,1.08,1.14])for(const da of [-18,-12,-6,0,6,12,18]){const radius=seed.radius*rf,angle=angleNorm(seed.angle+da),phase=structuralPhaseScoreFast(info.field,field,x,y,radius,angle);pushTop(phaseTop,{x,y,radius,angle,score:phase.score,phaseFast:phase.score},48)}}for(const item of phaseTop.slice(0,36)){const sparse=scoreAt(field,item.x,item.y,template(samples,item.radius,item.angle)),dense=denseStructuralScore(info.field,field,item.x,item.y,item.radius,item.angle),contour=bidirectionalContourScore(info.field,field,item.x,item.y,item.radius,item.angle),phase=structuralPhaseScore(info.field,field,item.x,item.y,item.radius,item.angle);item.sparseScore=sparse.score;item.structureScore=sparse.score;item.denseScore=dense.score;item.contourScore=contour.score;item.phaseScore=phase.score;item.rankScore=.04*Math.max(0,sparse.score)+.07*Math.max(0,dense.score)+.18*Math.max(0,contour.score)+.71*Math.max(0,phase.score)}phaseTop.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));hypotheses.push(phaseTop[0]||seed);await sleep(0)}hypotheses.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));const best=hypotheses[0],second=hypotheses.find(x=>x!==best&&Math.hypot(x.x-best.x,x.y-best.y)>=Math.max(12,best.radius*.48)),margin=second?(best.rankScore??best.phaseScore)-(second.rankScore??second.phaseScore):(best.rankScore??best.phaseScore);return{...best,score:best.structureScore??best.sparseScore??0,margin,atlas,hypotheses}}'''
text,n=re.subn(r'^async function coarseMatch\(info,cfg\)\{.*$',coarse,text,count=1,flags=re.M)
assert n==1,'coarseMatch replacement failed'

# Add truth diagnostics to the synthetic test so a future regression shows whether candidate generation or verification failed.
selftest=r'''async function selfTest(profile='gfn'){const cfg=MAPS[1],synth=await syntheticRoi(profile),info=roiSamples(synth.canvas),match=await globalMatch(info,cfg),fine=match.fine,coarse=match.coarse,scale=fine?.scaleFromCoarse||1,actual=fine?{x:fine.globalX/scale,y:fine.globalY/scale,radius:fine.radius/scale,angle:fine.angle}:null,error=actual?Math.hypot(actual.x-synth.expected.x,actual.y-synth.expected.y):Infinity,rotationError=actual?Math.min(angleDiff(actual.angle,synth.angle),angleDiff(angleNorm(actual.angle+180),synth.angle)):Infinity,gateReason=matchGate(coarse,fine,info,cfg),atlas=coarse?.atlas||await coarseAtlas(cfg),truthPhase=structuralPhaseScore(info.field,atlas.field,synth.expected.x,synth.expected.y,synth.radius,synth.angle),truthContour=bidirectionalContourScore(info.field,atlas.field,synth.expected.x,synth.expected.y,synth.radius,synth.angle),truthSparse=scoreAt(atlas.field,synth.expected.x,synth.expected.y,template(info.samples,synth.radius,synth.angle));return{ok:!!actual&&error<=10&&rotationError<=28&&!gateReason,profile,gateReason,error,rotationError,score:fine?.score??-1,denseScore:fine?.denseScore??-1,contourScore:fine?.contourScore??-1,phaseScore:fine?.phaseScore??-1,verifyScore:fine?.verifyScore??-1,topologyScore:fine?.topologyScore??-1,margin:fine?.margin??0,coarseScore:coarse?.score??-1,coarseMargin:coarse?.margin??0,truth:{phaseScore:truthPhase.score,ncc:truthPhase.ncc,contourScore:truthContour.score,sparseScore:truthSparse.score,radius:synth.radius,angle:synth.angle},expected:synth.expected,actual,features:info.samples.length,positiveFeatures:info.positiveCount,negativeFeatures:info.negativeCount,contrast:info.contrast}}'''
text,n=re.subn(r"^async function selfTest\(profile='gfn'\)\{.*$",selftest,text,count=1,flags=re.M)
assert n==1,'selfTest replacement failed'
path.write_text(text,'utf-8')
